        output_file=output_file,
        second_input_file=second_input_file,
        patch=patch,
        curv_overlay_files=curv_overlay_files,
        functional_data_file=functional_data_file,
        orig_positions=orig_positions,
        scale=scale,
        rescale=rescale,
        talairach_xfm=talairach_xfm,
